CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY AUTO_INCREMENT, name VARCHAR(100) NOT NULL, email VARCHAR(190) NOT NULL UNIQUE, password VARCHAR(255) NOT NULL, role VARCHAR(20) NOT NULL DEFAULT 'visitor', active INTEGER NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS categories (id INTEGER PRIMARY KEY AUTO_INCREMENT, name VARCHAR(80) NOT NULL UNIQUE, icon VARCHAR(30) NOT NULL DEFAULT 'store');
CREATE TABLE IF NOT EXISTS galleries (id INTEGER PRIMARY KEY AUTO_INCREMENT, name VARCHAR(120) NOT NULL, address VARCHAR(255) NOT NULL, description TEXT NOT NULL, simulated INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS floors (id INTEGER PRIMARY KEY AUTO_INCREMENT, gallery_id INTEGER NOT NULL, name VARCHAR(80) NOT NULL, level INTEGER NOT NULL, FOREIGN KEY(gallery_id) REFERENCES galleries(id));
CREATE TABLE IF NOT EXISTS nodes (id INTEGER PRIMARY KEY AUTO_INCREMENT, floor_id INTEGER NOT NULL, label VARCHAR(120) NOT NULL, kind VARCHAR(30) NOT NULL, x INTEGER NOT NULL, y INTEGER NOT NULL, FOREIGN KEY(floor_id) REFERENCES floors(id));
CREATE TABLE IF NOT EXISTS edges (id INTEGER PRIMARY KEY AUTO_INCREMENT, from_id INTEGER NOT NULL, to_id INTEGER NOT NULL, distance INTEGER NOT NULL, `accessible` INTEGER NOT NULL DEFAULT 1, active INTEGER NOT NULL DEFAULT 1, FOREIGN KEY(from_id) REFERENCES nodes(id), FOREIGN KEY(to_id) REFERENCES nodes(id));
CREATE TABLE IF NOT EXISTS businesses (id INTEGER PRIMARY KEY AUTO_INCREMENT, owner_id INTEGER, category_id INTEGER NOT NULL, node_id INTEGER, name VARCHAR(120) NOT NULL, description TEXT NOT NULL, address VARCHAR(255) NOT NULL, phone VARCHAR(40) NOT NULL, instagram VARCHAR(100) NOT NULL DEFAULT '', website VARCHAR(255) NOT NULL DEFAULT '', hours VARCHAR(255) NOT NULL, image VARCHAR(500) NOT NULL DEFAULT '', price_level VARCHAR(5) NOT NULL DEFAULT '$$', status VARCHAR(20) NOT NULL DEFAULT 'pending', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(owner_id) REFERENCES users(id), FOREIGN KEY(category_id) REFERENCES categories(id), FOREIGN KEY(node_id) REFERENCES nodes(id));
CREATE TABLE IF NOT EXISTS favorites (user_id INTEGER NOT NULL, business_id INTEGER NOT NULL, PRIMARY KEY(user_id,business_id), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(business_id) REFERENCES businesses(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS posts (id INTEGER PRIMARY KEY AUTO_INCREMENT, business_id INTEGER NOT NULL, title VARCHAR(160) NOT NULL, content TEXT NOT NULL, type VARCHAR(20) NOT NULL DEFAULT 'news', price DECIMAL(12,2), image VARCHAR(500) NOT NULL DEFAULT '', expires_at VARCHAR(10), status VARCHAR(20) NOT NULL DEFAULT 'published', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(business_id) REFERENCES businesses(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS reviews (id INTEGER PRIMARY KEY AUTO_INCREMENT, user_id INTEGER NOT NULL, business_id INTEGER NOT NULL, rating INTEGER NOT NULL, comment TEXT NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'published', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE(user_id,business_id), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(business_id) REFERENCES businesses(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS reports (id INTEGER PRIMARY KEY AUTO_INCREMENT, user_id INTEGER NOT NULL, business_id INTEGER NOT NULL, review_id INTEGER, reason TEXT NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'pending', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(business_id) REFERENCES businesses(id), FOREIGN KEY(review_id) REFERENCES reviews(id));
CREATE TABLE IF NOT EXISTS notifications (id INTEGER PRIMARY KEY AUTO_INCREMENT, user_id INTEGER NOT NULL, message VARCHAR(500) NOT NULL, is_read INTEGER NOT NULL DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS login_attempts (key_hash VARCHAR(64) PRIMARY KEY, attempts INTEGER NOT NULL DEFAULT 0, last_attempt INTEGER NOT NULL);
